"""Writes src/server/World/Mine/DioramaData.luau from tools/meshy/floor_layout.py outputs (do not edit by hand).

python3 -I tools/meshy/make_diorama_data.py src/server/World/Mine/DioramaData.luau <layout.json> [...]
"""
import json, sys

out = sys.argv[1]
L = ["--!strict", "--[[",
     "\tGenerated by tools/meshy/make_diorama_data.py from tools/meshy/floor_layout.py (do not edit by hand).",
     "\tThe owner's floor dioramas (Meshy, 2026-11-13) placed into their floors (Mine/Diorama.luau): Scale = studs",
     "\tper diorama unit, GroundN / CenterN = the diorama's usual ground height and its centre (units) that land on",
     "\tthe floor's origin, Boxes = invisible collision boxes as x0, z0, x1, z1, top (local studs, 5 numbers each),",
     "\tSpawns = rock spawns { x, y, z, deep }, Giant, Lights (local studs), the anchors found on flat ground.",
     "]]", "",
     "export type Floor = {", "\tScale: number,", "\tGroundN: number,", "\tCenterN: Vector2,", "\tTop: number,", "\tBottom: number,",
     "\tBoxes: { number },", "\tSpawns: { { any } },", "\tGiant: Vector3,", "\tLights: { Vector3 },", "\tAnchors: { [string]: Vector3 },", "}", "",
     "local DioramaData: { [string]: Floor } = {}", ""]
def r(v): return repr(round(v, 2))
for path in sys.argv[2:]:
    d = json.load(open(path))
    L.append("DioramaData.%s = {" % d["id"])
    L.append("\tScale = %s," % repr(d["scale"]))
    L.append("\tGroundN = %s," % repr(d["ground_n"]))
    L.append("\tCenterN = Vector2.new(%s, %s)," % (repr(d["center_n"][0]), repr(d["center_n"][1])))
    L.append("\tTop = %s," % r(d["top"]))
    L.append("\tBottom = %s," % r(d["bottom"]))
    L.append("\tBoxes = {")
    for b in d["boxes"]:
        L.append("\t\t%s, %s, %s, %s, %s," % tuple(r(v) for v in b))
    L.append("\t},")
    L.append("\tSpawns = {")
    for sp in d["spawns"]:
        L.append("\t\t{ %s, %s, %s, %s }," % (r(sp[0]), r(sp[1]), r(sp[2]), "true" if sp[3] else "false"))
    L.append("\t},")
    g = d["giant"]
    L.append("\tGiant = Vector3.new(%s, %s, %s)," % (r(g[0]), r(g[1]), r(g[2])))
    L.append("\tLights = {")
    for l in d.get("lights", []):
        L.append("\t\tVector3.new(%s, %s, %s)," % (r(l[0]), r(l[1]), r(l[2])))
    L.append("\t},")
    L.append("\tAnchors = {")
    for k, v in sorted(d.get("anchors", {}).items()):
        if v:
            L.append("\t\t%s = Vector3.new(%s, %s, %s)," % (k[0].upper() + k[1:], r(v[0]), r(v[1]), r(v[2])))
    L.append("\t},")
    L.append("}")
    L.append("")
L.append("return DioramaData")
open(out, "w").write("\n".join(L) + "\n")
print("wrote", out)
